    non_lazy = tmp_path / "non_lazy.txt"
    non_lazy.mkdir()
    result_in = runner.invoke(input_non_lazy, [f"--file={non_lazy}"])
    assert result_in.exit_code == 2
    assert f"Invalid value for '--file': '{non_lazy}'" in result_in.output

