    Uses the reproducer from https://github.com/pallets/click/issues/3458.
    """

    class Source(click.ParamType):
        name = "source"

        def convert(self, value, param, ctx):
            return {
                "value": value,
                "source": ctx.get_parameter_source(param.name),
            }

    @click.command()
